// Offline simulation: drives PolyriffProcessor::process() with a fake transport. Not a plug-in;
// build with `cmake --build build --target PolyriffSim`.
//
// Pattern core is checked against tests/golden.h -- tables generated by tools/gen_golden.js
// running the ORIGINAL Max JS (meshuggah-polymeter-core-live-step.js), so a match means the
// port is bit-exact with the patch. Transport/resync behavior is checked by replaying sessions
// and verifying every emitted note-on against the pattern with the expected rotation applied.
#include "polyriffprocessor.h"
#include "params.h"
#include "polyriffgen.h"
#include "golden.h"

#include "public.sdk/source/vst/hosting/eventlist.h"
#include "public.sdk/source/vst/hosting/parameterchanges.h"
#include "pluginterfaces/vst/ivstprocesscontext.h"

#include <algorithm>
#include <array>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <map>
#include <vector>

using namespace Steinberg;
using namespace Steinberg::Vst;
using namespace Polyriff;
using namespace Polyriff::golden;

static int failures = 0;
#define CHECK(c) do { if (!(c)) { std::printf ("CHECK FAILED line %d: %s\n", __LINE__, #c); ++failures; } } while (0)

namespace {

constexpr double kTempo = 120.;
constexpr double kSampleRate = 48000.;
constexpr int kBlock = 256;
constexpr double kPpqPerSample = kTempo / 60. / kSampleRate;
constexpr double kBlockPpq = kBlock * kPpqPerSample;

struct Ev
{
	double ppq {0.};
	int32 offset {0};
	int type {0};
	int pitch {0};
	int channel {0};
	int vel {0}; // 0..127, recovered from the float
	int noteId {0};
	bool flushed {false}; // note-off from a stop/jump flush: ppq is the flush point, not the gate end
};

struct Sim
{
	PolyriffProcessor proc;
	std::array<float, kBlock> l {}, r {}; // array, not vector: no heap, no brace-init gotcha
	float* chans[2] {nullptr, nullptr};
	AudioBusBuffers outBus {};
	EventList outEvents {512};
	ProcessContext ctx {};
	ProcessData data {};
	std::vector<Ev> evs;
	double lastEndPpq {0.};

	Sim ()
	{
		chans[0] = l.data ();
		chans[1] = r.data ();
		proc.initialize (nullptr); // null context: no CoreMIDI port in the sim
		ProcessSetup setup {kRealtime, kSample32, kBlock, kSampleRate};
		proc.setupProcessing (setup);
		proc.setActive (true);
		proc.setProcessing (true);
		outBus.numChannels = 2;
		outBus.channelBuffers32 = chans;
		data.numOutputs = 1;
		data.outputs = &outBus;
		data.outputEvents = &outEvents;
		data.processContext = &ctx;
		ctx.sampleRate = kSampleRate;
		ctx.tempo = kTempo;
		ctx.timeSigNumerator = 4;
		ctx.timeSigDenominator = 4;
	}
	~Sim ()
	{
		proc.setProcessing (false);
		proc.setActive (false);
	}

	// Plain-value parameter update, delivered in a stopped 0-sample block (tests only ever
	// set params between sessions, so no held notes are in flight at that point).
	void setParams (const std::vector<std::pair<int, double>>& params)
	{
		ParameterChanges changes;
		for (auto& [id, plain] : params)
		{
			int32 index = -1;
			IParamValueQueue* q =
			    changes.addParameterData (static_cast<Steinberg::Vst::ParamID> (id), index);
			q->addPoint (0, normFromPlain (static_cast<Steinberg::Vst::ParamID> (id), plain),
			             index);
		}
		outEvents.clear ();
		data.inputParameterChanges = &changes;
		data.numSamples = 0;
		ctx.state = ProcessContext::kTempoValid | ProcessContext::kProjectTimeMusicValid |
		            ProcessContext::kTimeSigValid;
		ctx.projectTimeMusic = 0.;
		proc.process (data);
		data.inputParameterChanges = nullptr;
	}

	void run (double ppq, bool playing, int num = kBlock, bool cycle = false, double cycleEnd = 0.)
	{
		ctx.state = ProcessContext::kTempoValid | ProcessContext::kProjectTimeMusicValid |
		            ProcessContext::kTimeSigValid | (playing ? ProcessContext::kPlaying : 0);
		if (cycle)
			ctx.state |= ProcessContext::kCycleValid | ProcessContext::kCycleActive;
		ctx.projectTimeMusic = ppq;
		ctx.cycleStartMusic = 0.;
		ctx.cycleEndMusic = cycleEnd;
		data.numSamples = num;
		outEvents.clear ();
		proc.process (data);
		for (int32 i = 0; i < outEvents.getEventCount (); ++i)
		{
			Event e;
			outEvents.getEvent (i, e);
			Ev v;
			v.ppq = e.ppqPosition;
			v.offset = e.sampleOffset;
			v.type = e.type;
			if (e.type == Event::kNoteOnEvent)
			{
				v.noteId = e.noteOn.noteId;
				v.pitch = e.noteOn.pitch;
				v.channel = e.noteOn.channel;
				v.vel = static_cast<int> (std::lround (e.noteOn.velocity * 127.f));
			}
			else if (e.type == Event::kNoteOffEvent)
			{
				v.noteId = e.noteOff.noteId;
				v.pitch = e.noteOff.pitch;
				v.channel = e.noteOff.channel;
				v.flushed = !playing; // a stopped run only emits flush note-offs
			}
			evs.push_back (v);
		}
		lastEndPpq = ppq + num * kPpqPerSample;
	}
};

void checkU8 (const char* what, const std::uint8_t* got, const std::uint8_t* want, int n)
{
	for (int i = 0; i < n; ++i)
	{
		if (got[i] != want[i])
		{
			std::printf ("%s[%d]: got %d want %d\n", what, i, got[i], want[i]);
			++failures;
			return;
		}
	}
}

void checkBool (const char* what, const bool* got, const std::uint8_t* want, int n)
{
	for (int i = 0; i < n; ++i)
	{
		if ((got[i] ? 1 : 0) != want[i])
		{
			std::printf ("%s[%d]: got %d want %d\n", what, i, got[i] ? 1 : 0, want[i]);
			++failures;
			return;
		}
	}
}

// Verifies a single continuous session started at ppq 0: every note-on falls on the 16th
// grid with the pattern value of idx = (S - lastBoundary) % n (lastBoundary = greatest
// multiple of `bound` <= S -- the rotation rule), every pattern slot with velocity > 0 has
// exactly one note-on, every note has exactly one note-off, and non-flushed note-offs land
// exactly gate/slide duration after their note-on.
void verifySession (const std::vector<Ev>& evs, const Pattern& pat, long long sMax, long long bound,
                    double gateBeats, int riffCh, int kickCh, const char* what)
{
	std::map<long long, Ev> riffOns, kickOns;
	std::map<int, const Ev*> onById, offById;
	bool bad = false;

	for (const auto& e : evs)
	{
		if (e.type == Event::kNoteOnEvent)
		{
			const long long S = static_cast<long long> (std::llround (e.ppq / kBeatsPerStep));
			if (std::fabs (e.ppq - S * kBeatsPerStep) > 1e-9)
			{
				std::printf ("%s: note-on off grid at ppq %.9f\n", what, e.ppq);
				++failures;
				bad = true;
			}
			auto& m = e.channel == riffCh ? riffOns : kickOns;
			if (!m.emplace (S, e).second)
			{
				std::printf ("%s: duplicate note-on lane ch=%d S=%lld\n", what, e.channel, S);
				++failures;
				bad = true;
			}
			onById[e.noteId] = &e;
		}
		else if (e.type == Event::kNoteOffEvent)
		{
			if (!offById.emplace (e.noteId, &e).second)
			{
				std::printf ("%s: duplicate note-off id=%d\n", what, e.noteId);
				++failures;
				bad = true;
			}
		}
	}
	if (bad)
		return;

	for (long long S = 0; S <= sMax; ++S)
	{
		const long long b = (S / bound) * bound;
		const int idx = static_cast<int> (((S - b) % pat.n + pat.n) % pat.n);
		for (int lane = 0; lane < 2; ++lane)
		{
			const bool isRiff = lane == 0;
			const auto& m = isRiff ? riffOns : kickOns;
			const std::uint8_t vel = isRiff ? pat.riffVel[idx] : pat.kickVel[idx];
			const auto it = m.find (S);
			if (vel > 0)
			{
				const int wantPitch = isRiff ? pat.pitch[idx] : kKickPitch;
				if (it == m.end ())
				{
					std::printf ("%s: missing %s note S=%lld idx=%d\n", what,
					             isRiff ? "riff" : "kick", S, idx);
					++failures;
				}
				else if (it->second.pitch != wantPitch || it->second.vel != vel)
				{
					std::printf ("%s: %s S=%lld idx=%d got pitch=%d vel=%d want pitch=%d vel=%d\n",
					             what, isRiff ? "riff" : "kick", S, idx, it->second.pitch,
					             it->second.vel, wantPitch, vel);
					++failures;
				}
			}
			else if (it != m.end ())
			{
				std::printf ("%s: unexpected %s note S=%lld idx=%d vel=%d\n", what,
				             isRiff ? "riff" : "kick", S, idx, it->second.vel);
				++failures;
			}
		}
	}

	for (auto& [id, on] : onById)
	{
		const auto offIt = offById.find (id);
		if (offIt == offById.end ())
		{
			std::printf ("%s: note-on id=%d never released\n", what, id);
			++failures;
			continue;
		}
		const Ev* off = offIt->second;
		if (off->flushed || off->ppq <= on->ppq)
			continue; // stop/jump flush: position is the flush point, not the gate end
		const long long S = static_cast<long long> (std::llround (on->ppq / kBeatsPerStep));
		const int idx = static_cast<int> (S % pat.n);
		const bool isRiff = on->channel == riffCh;
		const bool slide = isRiff ? pat.riffSlide[idx] : pat.kickSlide[idx];
		const double dur = slide ? std::max (gateBeats, 0.5) : gateBeats;
		if (std::fabs (off->ppq - (on->ppq + dur)) > 1e-9)
		{
			std::printf ("%s: note id=%d on=%.6f off=%.6f expected %.6f\n", what, id, on->ppq,
			             off->ppq, on->ppq + dur);
			++failures;
		}
	}
	for (auto& [id, off] : offById)
	{
		if (!onById.count (id))
		{
			std::printf ("%s: note-off id=%d without note-on\n", what, id);
			++failures;
		}
	}
}

// First riff note-on of a session (empty Ev on miss).
Ev firstRiffOn (const std::vector<Ev>& evs)
{
	for (const auto& e : evs)
		if (e.type == Event::kNoteOnEvent)
			return e;
	return {};
}

}

//------------------------------------------------------------------------
int main ()
{
	std::setvbuf (stdout, nullptr, _IONBF, 0);
	// ---- 1) RNG stream (pins mulberry32 against the JS output)
	{
		Rng32 rng (12345);
		for (int i = 0; i < 8; ++i)
		{
			const auto got = static_cast<std::uint32_t> (rng () * 4294967296.0);
			CHECK (got == kGoldenRng[i]);
		}
	}

	// ---- 2) pattern core vs golden (generated from the original Max JS)
	{
		GenParams gp = defaultGenParams ();
		{
			Rng32 rng (gp.seed);
			int sizes[kMaxSteps];
			const int n = makeGroups (21, gp.groupSpread, rng, sizes);
			CHECK (n == kGoldenGroups0Count);
			for (int i = 0; i < n && i < kGoldenGroups0Count; ++i)
				CHECK (sizes[i] == kGoldenGroups0[i]);
		}
		Pattern p;
		generatePattern (p, gp, 0);
		CHECK (p.n == 21);
		checkU8 ("pitch0", p.pitch, kGoldenPitch0, 21);
		checkU8 ("riffVel0", p.riffVel, kGoldenRiffVel0, 21);
		checkBool ("accent0", p.accent, kGoldenAccent0, 21);
		checkU8 ("kickVel0", p.kickVel, kGoldenKickVel0, 21);

		// density 0: only group starts hit; their pitch rolls still consume rng draws
		GenParams gd = gp;
		gd.density = 0;
		generatePattern (p, gd, 0);
		checkU8 ("riffVelD0", p.riffVel, kGoldenRiffVelD0, 21);
		checkU8 ("pitchD0", p.pitch, kGoldenPitchD0, 21);

		// kick mode 2 (Accent): kick only on group starts
		GenParams gm = gp;
		gm.kickMode = 2;
		generatePattern (p, gm, 0);
		checkU8 ("kickVelM2", p.kickVel, kGoldenKickVelM2, 21);

		// kick mode 0: kick silent
		gm.kickMode = 0;
		generatePattern (p, gm, 0);
		for (int i = 0; i < 21; ++i)
			CHECK (p.kickVel[i] == 0);

		// second profile: seed 999, spread 80, density 55, pitch 40/6/60, accent 100
		GenParams g1;
		g1.seed = 999;
		g1.groupSpread = 80;
		g1.density = 55;
		g1.pitchLow = 40;
		g1.pitchRange = 6;
		g1.pitchDensity = 60;
		g1.accentVel = 100;
		{
			Rng32 rng (g1.seed);
			int sizes[kMaxSteps];
			const int n = makeGroups (21, g1.groupSpread, rng, sizes);
			CHECK (n == kGoldenGroups1Count);
			for (int i = 0; i < n && i < kGoldenGroups1Count; ++i)
				CHECK (sizes[i] == kGoldenGroups1[i]);
		}
		generatePattern (p, g1, 0);
		checkU8 ("pitch1", p.pitch, kGoldenPitch1, 21);
		checkU8 ("riffVel1", p.riffVel, kGoldenRiffVel1, 21);
		checkBool ("accent1", p.accent, kGoldenAccent1, 21);
		checkU8 ("kickVel1", p.kickVel, kGoldenKickVel1, 21);

		// slides (display-order rolls depend on rotation): shift 0 and 5
		GenParams gs = defaultGenParams ();
		gs.slidePct = 40;
		generatePattern (p, gs, 0);
		checkBool ("riffSlide0", p.riffSlide, kGoldenRiffSlide0, 21);
		checkBool ("kickSlide0", p.kickSlide, kGoldenKickSlide0, 21);
		generatePattern (p, gs, 5);
		checkBool ("riffSlide5", p.riffSlide, kGoldenRiffSlide5, 21);
		checkBool ("kickSlide5", p.kickSlide, kGoldenKickSlide5, 21);

		// determinism: same params -> identical, different seed -> different
		Pattern a, b, c;
		generatePattern (a, defaultGenParams (), 0);
		generatePattern (b, defaultGenParams (), 0);
		CHECK (std::memcmp (&a, &b, sizeof (Pattern)) == 0);
		GenParams other = defaultGenParams ();
		other.seed = 999;
		generatePattern (c, other, 0);
		CHECK (std::memcmp (&a, &c, sizeof (Pattern)) != 0);

		// riff length clamps to 4..64
		GenParams gc = defaultGenParams ();
		gc.riffLen = 999;
		generatePattern (p, gc, 0);
		CHECK (p.n == 64);
		gc.riffLen = 1;
		generatePattern (p, gc, 0);
		CHECK (p.n == 4);
	}

	// ---- 3) parameter display strings: normalized -> text -> normalized
	{
		struct
		{
			Polyriff::ParamID id;
			double plain;
			const char* want;
		} cases[] = {
			{kSeed, 12345., "12345"}, {kRiffLen, 21., "21"},     {kHyperBars, 8., "8"},
			{kDensity, 70., "70"},     {kGroupSpread, 50., "50"}, {kPitchLow, 28., "28"},
			{kPitchRange, 3., "3"},    {kPitchDensity, 30., "30"},{kKickMode, 0., "Off"},
			{kKickMode, 1., "Follow"}, {kKickMode, 2., "Accent"}, {kAccentVel, 127., "127"},
			{kGatePct, 100., "100%"},  {kGatePct, 50., "50%"},    {kSlidePct, 0., "0"},
			{kRiffChannel, 1., "1"},   {kKickChannel, 16., "16"}, {kRandomize, 0., "Off"},
		};
		for (auto& c : cases)
		{
			const double norm = normFromPlain (c.id, c.plain);
			char buf[32];
			paramToString (c.id, norm, buf, sizeof (buf));
			if (std::strcmp (buf, c.want) != 0)
			{
				std::printf ("paramToString(%d, %g): got '%s' want '%s'\n", c.id, c.plain, buf, c.want);
				++failures;
			}
			double back = -1.;
			CHECK (paramFromString (c.id, buf, back));
			CHECK (std::fabs (back - norm) < 1e-9);
		}
		double v = -1.;
		// seed text entry: numeric string -> value, anything else -> FNV-1a
		CHECK (paramFromString (kSeed, "12345", v) &&
		       static_cast<std::uint32_t> (plainFromNorm (kSeed, v)) == 12345u);
		CHECK (paramFromString (kSeed, "hello", v) &&
		       static_cast<std::uint32_t> (plainFromNorm (kSeed, v)) == kGoldenFnvHello);
		CHECK (paramFromString (kSeed, "4000000000", v) &&
		       static_cast<std::uint32_t> (plainFromNorm (kSeed, v)) == 4000000000u);
		CHECK (paramFromString (kSeed, " 17 ", v) &&
		       static_cast<std::uint32_t> (plainFromNorm (kSeed, v)) == 17u);
		CHECK (paramFromString (kKickMode, "follow", v) &&
		       std::fabs (plainFromNorm (kKickMode, v) - 1.) < 1e-9);
		CHECK (!paramFromString (kDensity, "abc", v));
		// out-of-range plain values clamp
		CHECK (normFromPlain (kRiffLen, 999.) == 1.0);
		CHECK (normFromPlain (kAccentVel, 0.) == 0.0);
		CHECK (normFromPlain (kGatePct, 0.) == 0.0);
	}

	// ---- 4) transport: default session (L=8, N=21), every note verified against the
	//         pattern with the boundary rotation rule (boundary steps = 16*8 = 128)
	{
		Sim s;
		for (double p = 0.; p < 33.0; p += kBlockPpq)
			s.run (p, true);
		const double end = s.lastEndPpq;
		s.run (33.0, false); // stop -> flush the last held note
		Pattern p;
		generatePattern (p, defaultGenParams (), 0);
		const long long sMax =
		    static_cast<long long> (std::ceil (end / kBeatsPerStep - 1e-9)) - 1;
		verifySession (s.evs, p, sMax, 128, 0.25, 0, 1, "default8bar");
		CHECK (!s.evs.empty ());
		for (const auto& e : s.evs)
		{
			if (e.type == Event::kNoteOnEvent)
				CHECK (e.channel == 0 || e.channel == 1);
			if (e.type == Event::kNoteOnEvent && e.channel == 1)
				CHECK (e.pitch == kKickPitch);
		}
		std::printf ("default 8-bar session: %zu events\n", s.evs.size ());
	}

	// ---- 5) hyperBars=1: resync every bar (rotation shifts each 16 steps, N=21 tail)
	{
		Sim s;
		s.setParams ({{kHyperBars, 1}});
		for (double p = 0.; p < 8.5; p += kBlockPpq)
			s.run (p, true);
		const double end = s.lastEndPpq;
		s.run (8.5, false);
		Pattern p;
		generatePattern (p, defaultGenParams (), 0);
		const long long sMax =
		    static_cast<long long> (std::ceil (end / kBeatsPerStep - 1e-9)) - 1;
		verifySession (s.evs, p, sMax, 16, 0.25, 0, 1, "hyper1");
		std::printf ("hyperBars=1 session verified\n");
	}

	// ---- 6) density 100: every 16th fires on both lanes (mode Follow)
	{
		Sim s;
		s.setParams ({{kDensity, 100.}});
		for (double p = 0.; p < 2.0; p += kBlockPpq)
			s.run (p, true);
		const double end = s.lastEndPpq;
		s.run (2.0, false);
		GenParams gp = defaultGenParams ();
		gp.density = 100;
		Pattern p;
		generatePattern (p, gp, 0);
		const long long sMax =
		    static_cast<long long> (std::ceil (end / kBeatsPerStep - 1e-9)) - 1;
		verifySession (s.evs, p, sMax, 128, 0.25, 0, 1, "density100");
		int riffCount = 0;
		for (const auto& e : s.evs)
			if (e.type == Event::kNoteOnEvent && e.channel == 0)
				++riffCount;
		CHECK (riffCount == sMax + 1);
	}

	// ---- 7) jump rules (Max change->expr->sel semantics)
	{
		// (a) playStart on a boundary bar -> resync: riff[0] plays exactly there.
		//     Without resync idx(128) = 2, which is a rest -> no note at 32.0 at all.
		Sim s;
		s.run (32., true);
		s.run (32.1, true);
		s.run (32.2, false);
		bool found = false;
		for (const auto& e : s.evs)
			if (e.type == Event::kNoteOnEvent && e.channel == 0 && e.ppq == 32.0)
			{
				found = true;
				CHECK (e.pitch == kGoldenPitch0[0]);
				CHECK (e.vel == kGoldenRiffVel0[0]);
			}
		CHECK (found);

		// (b) playStart in the middle of a NON-boundary bar keeps the previous rotation.
		//     Session 1 crosses the boundary at 32 (rotShift = 128 % 21 = 2), stops, then
		//     starts at 36 (bar 9, 9 % 8 != 0): idx(144) = 16 -> pitch0[16]=28 vel=95.
		//     Cleared rotation would give idx 18 (pitch 29); landing resync would give
		//     idx 0 (accent vel 127).
		Sim t;
		for (double p = 28.; p < 40.; p += kBlockPpq)
			t.run (p, true);
		t.run (40., false);
		t.evs.clear ();
		for (double p = 36.; p < 36.5; p += kBlockPpq)
			t.run (p, true);
		t.run (36.5, false);
		const Ev first = firstRiffOn (t.evs);
		CHECK (first.ppq == 36.0);
		CHECK (first.pitch == kGoldenPitch0[16]);
		CHECK (first.vel == kGoldenRiffVel0[16]);

		// (c) seed change clears the rotation (JS clearRot): same session shape but the
		//     params switch to golden profile 1 first; idx(144) = 144 % 21 = 18 ->
		//     pitch1[18]=40 vel1[18]=100. Kept rotation would give idx 16 (vel 75),
		//     landing resync would give idx 0 (pitch 42).
		Sim u;
		for (double p = 28.; p < 40.; p += kBlockPpq)
			u.run (p, true);
		u.run (40., false);
		u.setParams ({{kSeed, 999.},
		              {kGroupSpread, 80.},
		              {kDensity, 55.},
		              {kPitchLow, 40.},
		              {kPitchRange, 6.},
		              {kPitchDensity, 60.},
		              {kAccentVel, 100.}});
		u.evs.clear ();
		for (double p = 36.; p < 36.5; p += kBlockPpq)
			u.run (p, true);
		u.run (36.5, false);
		const Ev first1 = firstRiffOn (u.evs);
		CHECK (first1.ppq == 36.0);
		CHECK (first1.pitch == kGoldenPitch1[18]);
		CHECK (first1.vel == kGoldenRiffVel1[18]);
	}

	// ---- 8) stop flush: every note-on gets exactly one note-off
	{
		Sim s;
		s.run (0.99, true);  // block contains the step at 1.0 (gate ends 1.25)
		s.run (1.02, true);
		s.run (1.10, false); // stop while the 1.0 note is still held
		std::map<int, int> balance;
		int ons = 0, offs = 0;
		for (const auto& e : s.evs)
		{
			if (e.type == Event::kNoteOnEvent)
			{
				++ons;
				++balance[e.noteId];
			}
			else if (e.type == Event::kNoteOffEvent)
			{
				++offs;
				--balance[e.noteId];
			}
		}
		CHECK (ons > 0);
		CHECK (offs == ons);
		for (auto& [id, v] : balance)
			CHECK (v == 0);
	}

	// ---- 9) stopped transport emits nothing (Live keeps calling process while stopped)
	{
		Sim s;
		for (int i = 0; i < 5; ++i)
			s.run (2.0, false);
		CHECK (s.evs.empty ());
	}

	// ---- 10) loop wrap: split block at cycle end, ghost clamp, jump re-seat
	{
		Sim s;
		int pastEnd = 0;
		for (int pass = 0; pass < 3; ++pass)
		{
			double p = 0.;
			while (p + kBlockPpq < 2.0)
			{
				s.run (p, true, kBlock, true, 2.0);
				p += kBlockPpq;
			}
			const int n = static_cast<int> ((2.0 - p) / kPpqPerSample) + 1;
			s.run (p, true, n, true, 2.0); // overshoots the loop end; next block starts at 0
		}
		for (const auto& e : s.evs)
			if (e.type == Event::kNoteOnEvent && e.ppq >= 2.0 + 1e-9)
				++pastEnd;
		CHECK (pastEnd == 0);
		s.run (2.0, false);
		std::map<int, int> balance;
		int ons = 0, offs = 0;
		for (const auto& e : s.evs)
		{
			if (e.type == Event::kNoteOnEvent) { ++ons; ++balance[e.noteId]; }
			if (e.type == Event::kNoteOffEvent) { ++offs; --balance[e.noteId]; }
		}
		CHECK (ons > 0);
		CHECK (offs == ons);
		for (auto& [id, v] : balance)
			CHECK (v == 0);
		std::printf ("loop wrap ons=%d offs=%d\n", ons, offs);
	}

	// ---- 11) gate/slide durations (kick off to isolate the riff lane)
	{
		struct
		{
			int gatePct;
			int slidePct;
			double dur;
			const char* what;
		} cases[] = {
			{100, 0, 0.25, "gate100"},
			{50, 0, 0.125, "gate50"},
			{200, 0, 0.5, "gate200"},
			{100, 100, 0.5, "slide100"}, // density 100 + slide 100 -> every hit slides
		};
		for (auto& c : cases)
		{
			Sim s;
			s.setParams ({{kGatePct, static_cast<double> (c.gatePct)},
			              {kSlidePct, static_cast<double> (c.slidePct)},
			              {kDensity, 100.},
			              {kKickMode, 0.}});
			for (double p = 0.; p < 2.0; p += kBlockPpq)
				s.run (p, true);
			s.run (2.5, false); // well past every gate end -> all offs are clean gate ends
			int checked = 0;
			std::map<int, const Ev*> ons;
			for (const auto& e : s.evs)
				if (e.type == Event::kNoteOnEvent)
					ons[e.noteId] = &e;
			for (const auto& e : s.evs)
			{
				if (e.type != Event::kNoteOffEvent || e.flushed)
					continue; // stop-flush offs carry the stop position, not the gate end
				const auto it = ons.find (e.noteId);
				if (it == ons.end () || e.ppq <= it->second->ppq)
					continue;
				if (std::fabs (e.ppq - (it->second->ppq + c.dur)) > 1e-9)
				{
					std::printf ("%s: off %.6f - on %.6f != %.6f\n", c.what, e.ppq,
					             it->second->ppq, c.dur);
					++failures;
				}
				++checked;
			}
			CHECK (checked > 4);
			std::printf ("%s: %d durations checked\n", c.what, checked);
		}
	}

	// ---- 12) channel params route the lanes
	{
		Sim s;
		s.setParams ({{kRiffChannel, 3.}, {kKickChannel, 4.}});
		for (double p = 0.; p < 1.0; p += kBlockPpq)
			s.run (p, true);
		s.run (1.0, false);
		int riff = 0, kick = 0;
		for (const auto& e : s.evs)
		{
			if (e.type != Event::kNoteOnEvent)
				continue;
			if (e.channel == 2)
				++riff;
			else if (e.channel == 3)
			{
				++kick;
				CHECK (e.pitch == kKickPitch);
			}
			else
			{
				std::printf ("unexpected channel %d\n", e.channel);
				++failures;
			}
		}
		CHECK (riff > 0);
		CHECK (kick > 0);
	}

	// ---- 13) determinism across processor instances
	{
		auto session = [] (std::uint32_t seed) {
			Sim s;
			s.setParams ({{kSeed, static_cast<double> (seed)}});
			std::vector<Ev> out;
			for (double p = 0.; p < 2.0; p += kBlockPpq)
				s.run (p, true);
			return s.evs;
		};
		const auto a = session (12345);
		const auto b = session (12345);
		const auto c = session (424242);
		CHECK (a.size () == b.size () && a.size () > 0);
		bool same = a.size () == b.size ();
		for (size_t i = 0; same && i < a.size (); ++i)
			same = a[i].ppq == b[i].ppq && a[i].pitch == b[i].pitch &&
			       a[i].vel == b[i].vel && a[i].channel == b[i].channel;
		CHECK (same);
		bool differs = a.size () != c.size ();
		for (size_t i = 0; !differs && i < a.size (); ++i)
			differs = a[i].pitch != c[i].pitch || a[i].vel != c[i].vel ||
			         a[i].ppq != c[i].ppq;
		CHECK (differs);
	}

	std::printf (failures ? "FAILED (%d)\n" : "ALL OK\n", failures);
	return failures;
}
